  sway = Math.sin(bt * Math.PI) * 12 * eAmp;
  bob = -Math.abs(Math.sin(sb * Math.PI)) * 10 * eAmp - kick * 4 * eAmp;
  squash = 1 + kick * .08 * eAmp;
  aL = -.8 - Math.sin(bt * Math.PI) * .8 * eAmp; aR = .8 + Math.sin(bt * Math.PI) * .8 * eAmp;
